// main.js: the map-quiz engine: map view (zoom, pan), input, HUD and
// persistence. The rules live in quiz.js; everything about one image comes
// from its config.js (regions, rounds, texts; contract:
// shared/map-quiz/README.md) and map.svg (generated by the image's
// tools/build_map.py, like the data module config.js imports).
// Shared map-quiz engine file: the source is shared/map-quiz/site/, images
// get byte-identical copies (python3 shared/sync.py). Edit the source.
//
// Map: map.svg is fetched and inserted inline, so style.css styles it. The
// view is a camera, screen = map * s + t (CSS px); the SVG's viewBox is set
// to the visible map rectangle each frame, so strokes stay crisp
// (vector-effect: non-scaling-stroke) and a tap is tested against the real
// shapes (elementFromPoint). Zoom: s from the full view (fitScale, the
// whole map inside the free area between the HUD bands) to MAX_SCALE px
// per map unit; pan: the map keeps covering the free area where it is
// larger, and stays inside it where it is smaller. Beyond the full view
// map.svg draws context land, fading out, so wide or tall screens show map
// rather than an empty band.
//
// Pieces and answers: map.svg has one shape per piece (config.items); a
// round's answers are its pieces one by one, or groups of them
// (rounds[].answers, normalised by contract.js roundSpecs). A piece in no
// answer of the round is inert (class "inert": context land for that
// round). Hover, colours and blinks act on all pieces of an answer (plus
// its ring); colours are per piece, a ring shows the colour its pieces
// share. A round may list line overlays (rounds[].lines, e.g. coasts and
// borders drawn from mapgen's shared arcs): those show in that round
// only, and its pieces draw an outline in their own fill ("seamless"), so
// no hairline shows between the pieces of a group.
//
// Input: a press that moves more than SLOP px is a pan, never a click; two
// fingers pinch-zoom (and pan); a mouse wheel zooms at the cursor, a
// trackpad's two-finger scroll pans (onWheel; wheel.js decides per gesture), and
// a pinch or ctrl + wheel anywhere on the page zooms the map, not the page;
// buttons and + / - / 0 / arrow keys zoom and pan with a short animation. A click
// picks a small answer's ring if it lands inside the drawn ring, or within
// MARKER_HIT px of it over sea, context land, an inert piece or that answer
// itself (never over another answer); the nearest such ring wins. Otherwise
// it picks the answer of the piece under the pointer; sea, context land,
// inert pieces and overlays (drawn above the regions, pointer-events:
// none) are ignored or see-through, except a blocking overlay
// (config.blockingOverlays, e.g. water): its fill and outline count as
// background (no answer, no misclick, no hover). Rings belong to the
// round's answers (rebuilt when a round's set differs) and shrink at low
// zoom (MARKER_R_UNITS), so they don't cover their neighbours on a phone.
//
// State on <html>: data-round (the round's config key, e.g. countries |
// capitals), data-progress ("12/46"), data-zoom (s / fitScale), data-ready
// (1 once the map is in; "error" if it failed), data-wheel (how the last
// wheel event was taken: trackpad | mouse | pinch). Read: data-quiz, the
// image's folder name, which namespaces localStorage ("phw-<name>"); the
// engine doesn't start without it. Quiz state
// and counters persist there (optional). Debug: ?seed=<int> (0 …
// 4294967295, digits only) makes the shuffles reproducible (stored state
// with another seed is replaced).

import config from './config.js';
import { checkConfig, roundSpecs } from './contract.js';
import { Quiz } from './quiz.js';
import { wheelKind } from './wheel.js';

const root = document.documentElement;
const NAME = /^[a-z0-9]+([._-][a-z0-9]+)*$/; // an image folder name

// Starting needs a config that fits the contract and <html data-quiz>; else
// the page says so (data-ready="error", a toast; the details in the
// console) and the engine stops here.
let SPECS = null; // per round: { key, answers: [{ id, pieces }], asked, byId } (contract.js)
try {
  checkConfig(config);
  SPECS = roundSpecs(config);
  if (!NAME.test(root.dataset.quiz || '')) throw new Error('index.html: <html data-quiz="<image folder name>"> is missing or not a folder name (it namespaces localStorage)');
} catch (err) {
  root.dataset.ready = 'error';
  const t = document.getElementById('toast');
  const own = config && config.text && config.text.mapError;
  if (t) {
    t.textContent = typeof own === 'string' && own ? own : 'This page could not start. Details are in the browser console.';
    t.classList.add('show');
  }
  throw err;
}
const { map: MAP, items: ITEMS, rounds: ROUNDS, text: TEXT } = config;
const LANDSCAPE = '(min-aspect-ratio: 4/3)'; // same query as in style.css
const PAD = 12; // CSS px between the map (full view) and the edges / HUD bands
const MAX_SCALE = (config.view && config.view.maxScale) || 12; // CSS px per map unit at the closest zoom (maps are 1000 units wide)
const BESIDE_HUD = !!(config.view && config.view.besideHud); // landscape: full view left of the card + controls
const MIN_ZOOM_RANGE = 4; // … but at least this many times the full view
const ZOOM_STEP = 1.75; // buttons and keys
const ANIM_MS = 260;
const LABEL_MS = 1500;
const PULSE_MS = 700;
const TOAST_MS = 4000;
const RESET_ARM_MS = 3000;
const SLOP = { mouse: 5, pen: 8, touch: 10 }; // px of movement that make a press a pan
const MARKER_R = 7; // ring radius, CSS px …
const MARKER_R_UNITS = 11; // … but at most this many map units at low zoom …
const MARKER_R_MIN = 4; // … and at least this many px
const RING_SLACK = 2; // px around the drawn ring that count as inside (its halo)
const MARKER_HIT = { mouse: 14, pen: 18, touch: 22 }; // wider hit zone around a ring, CSS px
const MARKER_HIDE = 28; // a ring hides once its region is this many CSS px across
const WHEEL_GAP_MS = 200; // wheel events closer than this belong to one gesture

const STATE_KEY = 'phw-' + root.dataset.quiz;
const host = document.getElementById('map');
const card = document.getElementById('card');
const controls = document.getElementById('controls');
const roundEl = document.getElementById('round');
const progressEl = document.getElementById('progress');
const correctEl = document.getElementById('correct');
const missesEl = document.getElementById('misses');
const promptEl = document.getElementById('prompt');
const promptKind = document.getElementById('prompt-kind');
const promptText = document.getElementById('prompt-text');
const toastEl = document.getElementById('toast');
const labelEl = document.getElementById('label');
const safe = document.getElementById('safe');
const resetButton = document.getElementById('reset');
const zoomIn = document.getElementById('zoom-in');
const zoomOut = document.getElementById('zoom-out');
const zoomFit = document.getElementById('zoom-fit');
const themeButton = document.getElementById('theme');
const swatch = document.querySelector('#card .swatch');

const SVG_NS = 'http://www.w3.org/2000/svg';
const ids = ITEMS.map((c) => c.id); // the pieces
const landscape = matchMedia(LANDSCAPE);
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
const coarse = matchMedia('(pointer: coarse)').matches;

const params = new URLSearchParams(location.search);
const seedText = params.get('seed') || '';
const seedParam = /^\d{1,10}$/.test(seedText) && Number(seedText) <= 0xffffffff ? Number(seedText) : null;

// ── Quiz state ──────────────────────────────────────────────────────────

function loadState() {
  try {
    return JSON.parse(localStorage.getItem(STATE_KEY) || 'null');
  } catch {
    return null;
  }
}

function save() {
  try {
    localStorage.setItem(STATE_KEY, JSON.stringify(quiz.serialize()));
  } catch {
    // storage blocked (private mode etc.): the quiz lasts this visit
  }
}

const QUIZ_OPTIONS = { carryColours: config.carryColours !== false }; // false: every round starts blank
const restored = Quiz.restore(loadState(), ids, SPECS, QUIZ_OPTIONS);
const resumed = !!restored && (seedParam === null || restored.seed === seedParam);
const quiz = resumed
  ? restored
  : new Quiz(ids, seedParam ?? crypto.getRandomValues(new Uint32Array(1))[0], SPECS, QUIZ_OPTIONS);

// ── Map elements ────────────────────────────────────────────────────────

let svg = null;
let regionsG = null; // the group of piece shapes (class "regions")
const shapes = {}; // piece id -> <path>
const blockers = []; // <path>s of config.blockingOverlays
let blockPoint = null; // an SVGPoint, reused by blocked()
const lineEls = new Map(); // overlay id -> <path> of every round's lines (class "line")
let markersG = null; // #markers, if any round has rings
let ringSet = null; // what the rings in #markers were built from
const rings = new Map(); // answer id (this round) -> { g, halo, ring, x, y, size, on, r (drawn radius, px) }

// Four gradient bands along the edge of the drawn extent (style.css fills
// them with the sea colour, opaque at the edge), over the outer half of the
// context around the full view. They overhang the extent by a few units to
// cover the land outline's half-stroke along the clip edge.
function fade() {
  const o = 4;
  const [ex, ey, ew, eh] = [MAP.extent[0] - o, MAP.extent[1] - o, MAP.extent[2] + 2 * o, MAP.extent[3] + 2 * o];
  const fx = -MAP.extent[0] / 2 + o;
  const fy = -MAP.extent[1] / 2 + o;
  const g = svgEl('g', { id: 'fade' });
  const defs = svgEl('defs', {});
  const bands = {
    t: [[0, 0, 0, 1], [ex, ey, ew, fy]],
    b: [[0, 1, 0, 0], [ex, ey + eh - fy, ew, fy]],
    l: [[0, 0, 1, 0], [ex, ey, fx, eh]],
    r: [[1, 0, 0, 0], [ex + ew - fx, ey, fx, eh]],
  };
  for (const [k, [[x1, y1, x2, y2], [x, y, width, height]]] of Object.entries(bands)) {
    const grad = svgEl('linearGradient', { id: `fade-g${k}`, x1, y1, x2, y2 });
    // eased (smoothstep-like), so the fade has no visible inner edge
    [0, 0.25, 0.5, 0.75, 1].forEach((offset, i) => grad.append(svgEl('stop', { offset, class: `fade-${i}` })));
    defs.append(grad);
    g.append(svgEl('rect', { id: `fade-${k}`, x, y, width, height }));
  }
  g.prepend(defs);
  return g;
}

function svgEl(name, attrs) {
  const el = document.createElementNS(SVG_NS, name);
  for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
  return el;
}

// The elements that show an answer's state: the shapes of its pieces and
// its ring (rings change only in enterRound()). targets(id): as the
// current round has the answer; after quiz.answer(), its result's pieces
// say which pieces the answer had in the round it was given in.
function elsOf(id, pieces) {
  const t = pieces.map((p) => shapes[p]).filter(Boolean);
  if (rings.has(id)) t.push(rings.get(id).ring);
  return t;
}

const targets = (id) => elsOf(id, quiz.piecesOf(id));

function setColour(el, c) {
  el.classList.toggle('c1', c === 1);
  el.classList.toggle('c2', c === 2);
}

// A ring shows the colour all its answer's pieces share (none while they differ).
function ringColour(pieces) {
  const c = quiz.colourOf(pieces[0]);
  return pieces.every((p) => quiz.colourOf(p) === c) ? c : 0;
}

function paintPieces(pieces) {
  for (const p of pieces) if (shapes[p]) setColour(shapes[p], quiz.colourOf(p));
}

function paintAll() {
  paintPieces(ids);
  for (const [id, m] of rings) setColour(m.ring, ringColour(quiz.piecesOf(id)));
}

// Adds a class to elements for `ms` (restarting its CSS animation if it is
// running). Each element remembers its timers, so undoing never depends on
// which pieces an answer has by then.
const markTimers = new Map(); // element -> { class: timeout }
function markEls(els, cls, ms) {
  if (!els.length) return;
  for (const el of els) el.classList.remove(cls);
  void els[0].getBoundingClientRect();
  for (const el of els) {
    el.classList.add(cls);
    const t = markTimers.get(el) || {};
    clearTimeout(t[cls]);
    t[cls] = setTimeout(() => unmarkEls([el], cls), ms);
    markTimers.set(el, t);
  }
}

function unmarkEls(els, cls) {
  for (const el of els) {
    const t = markTimers.get(el);
    if (t) {
      clearTimeout(t[cls]);
      delete t[cls];
      if (!Object.keys(t).length) markTimers.delete(el);
    }
    el.classList.remove(cls);
  }
}

// Ends every mark on these elements now (timers dropped).
function clearMarksOf(els) {
  for (const el of els) {
    const t = markTimers.get(el);
    if (!t) continue;
    for (const [cls, timer] of Object.entries(t)) {
      clearTimeout(timer);
      el.classList.remove(cls);
    }
    markTimers.delete(el);
  }
}

function clearMarks() {
  clearMarksOf([...markTimers.keys()]);
}

// ── Camera ──────────────────────────────────────────────────────────────

let cam = { s: 1, tx: 0, ty: 0 };
let view = { w: 1, h: 1 };
let free = { x0: 0, y0: 0, x1: 1, y1: 1 }; // where the full view goes, CSS px
let fitScale = 1;
let renderQueued = false;
let anim = 0; // rAF id of a camera animation
let animTarget = null;

const maxScale = () => Math.max(MAX_SCALE, fitScale * MIN_ZOOM_RANGE);
const clampScale = (s) => Math.min(maxScale(), Math.max(fitScale, s));
const freeCentre = () => ({ x: (free.x0 + free.x1) / 2, y: (free.y0 + free.y1) / 2 });

function insets() {
  const cs = getComputedStyle(safe);
  const px = (k) => parseFloat(cs[k]) || 0;
  return { t: px('paddingTop'), r: px('paddingRight'), b: px('paddingBottom'), l: px('paddingLeft') };
}

function measure() {
  const r = host.getBoundingClientRect();
  view = { w: Math.max(1, r.width), h: Math.max(1, r.height) };
  const ins = insets();
  let y0 = ins.t + PAD;
  let y1 = view.h - ins.b - PAD;
  let x1 = view.w - ins.r - PAD;
  if (!landscape.matches) {
    // The card and the controls run across the screen: keep the full view
    // between them.
    y0 = Math.max(y0, card.getBoundingClientRect().bottom + PAD);
    y1 = Math.min(y1, controls.getBoundingClientRect().top - PAD);
  } else {
    // The card covers a corner of the full view unless config.view.besideHud
    // keeps it left of the card and the controls column; never under the
    // attribution line (bottom left).
    if (BESIDE_HUD) x1 = Math.min(x1, card.getBoundingClientRect().left - PAD, controls.getBoundingClientRect().left - PAD);
    const attr = document.getElementById('attribution');
    if (attr) y1 = Math.min(y1, attr.getBoundingClientRect().top - PAD);
  }
  free = { x0: ins.l + PAD, y0, x1: Math.max(ins.l + PAD + 40, x1), y1: Math.max(y0 + 40, y1) };
  fitScale = Math.min((free.x1 - free.x0) / MAP.width, (free.y1 - free.y0) / MAP.height);
}

// Keeps the map covering the free area on each axis where it is larger,
// and inside it where it is smaller (centre: fitView). So a zoom stays
// exactly at the cursor, also before the map fills the screen.
function clamp(c) {
  const s = clampScale(c.s);
  const axis = (t, size, lo, hi) => {
    const len = size * s;
    return len <= hi - lo ? Math.min(hi - len, Math.max(lo, t)) : Math.min(lo, Math.max(hi - len, t));
  };
  return { s, tx: axis(c.tx, MAP.width, free.x0, free.x1), ty: axis(c.ty, MAP.height, free.y0, free.y1) };
}

// The full view: fit scale, centred in the free area.
function fitCam() {
  const s = fitScale;
  return { s, tx: (free.x0 + free.x1 - MAP.width * s) / 2, ty: (free.y0 + free.y1 - MAP.height * s) / 2 };
}

const num = (v) => String(Math.round(v * 1000) / 1000);

function render() {
  renderQueued = false;
  if (!svg) return;
  const { s, tx, ty } = cam;
  svg.setAttribute('viewBox', `${num(-tx / s)} ${num(-ty / s)} ${num(view.w / s)} ${num(view.h / s)}`);
  const rpx = Math.min(MARKER_R, Math.max(MARKER_R_MIN, MARKER_R_UNITS * s));
  const r = num(rpx / s);
  for (const m of rings.values()) {
    const on = m.size * s < MARKER_HIDE;
    if (on !== m.on) {
      m.on = on;
      m.g.classList.toggle('off', !on);
    }
    m.r = rpx;
    if (on) {
      m.halo.setAttribute('r', r);
      m.ring.setAttribute('r', r);
    }
  }
  const z = s / fitScale;
  const f = fitCam();
  root.dataset.zoom = z.toFixed(2);
  zoomIn.setAttribute('aria-disabled', String(s >= maxScale() - 1e-6));
  zoomOut.setAttribute('aria-disabled', String(z <= 1 + 1e-6));
  zoomFit.setAttribute('aria-disabled', String(z <= 1 + 1e-6 && Math.abs(tx - f.tx) < 1 && Math.abs(ty - f.ty) < 1));
}

function queueRender() {
  if (!renderQueued) {
    renderQueued = true;
    requestAnimationFrame(render);
  }
}

function setCam(c) {
  cam = clamp(c);
  queueRender();
}

function stopAnim() {
  if (anim) cancelAnimationFrame(anim);
  anim = 0;
  animTarget = null;
}

// Eases to a camera: the scale geometrically, the map point at the centre
// of the free area linearly. Instant with reduced motion.
function animateTo(c) {
  stopAnim();
  const to = clamp(c);
  if (reducedMotion.matches) {
    setCam(to);
    return;
  }
  const from = { ...cam };
  const { x: cx, y: cy } = freeCentre();
  const m0 = { x: (cx - from.tx) / from.s, y: (cy - from.ty) / from.s };
  const m1 = { x: (cx - to.tx) / to.s, y: (cy - to.ty) / to.s };
  const t0 = performance.now();
  animTarget = to;
  const step = (now) => {
    const t = Math.min(1, (now - t0) / ANIM_MS);
    const e = 1 - Math.pow(1 - t, 3);
    const s = from.s * Math.pow(to.s / from.s, e);
    cam = { s, tx: cx - (m0.x + (m1.x - m0.x) * e) * s, ty: cy - (m0.y + (m1.y - m0.y) * e) * s };
    if (t >= 1) {
      cam = to;
      anim = 0;
      animTarget = null;
    } else {
      anim = requestAnimationFrame(step);
    }
    render();
  };
  anim = requestAnimationFrame(step);
}

function zoomAt(x, y, factor) {
  const s = clampScale(cam.s * factor);
  const k = s / cam.s;
  setCam({ s, tx: x - (x - cam.tx) * k, ty: y - (y - cam.ty) * k });
}

function panBy(dx, dy) {
  setCam({ s: cam.s, tx: cam.tx + dx, ty: cam.ty + dy });
}

// Buttons and keys: zoom at the centre of the free area; repeated presses
// during an animation build on its target.
function zoomStep(factor) {
  const base = animTarget || cam;
  const { x, y } = freeCentre();
  const s = clampScale(base.s * factor);
  const k = s / base.s;
  animateTo({ s, tx: x - (x - base.tx) * k, ty: y - (y - base.ty) * k });
}

function panStep(fx, fy) {
  const base = animTarget || cam;
  animateTo({ s: base.s, tx: base.tx + fx * (free.x1 - free.x0) * 0.3, ty: base.ty + fy * (free.y1 - free.y0) * 0.3 });
}

function fitView(animated) {
  const c = fitCam();
  if (animated) animateTo(c);
  else setCam(c);
}

// Window resized: keep the zoom relative to the full view and the map point
// at the centre of the free area.
function relayout() {
  const z = cam.s / fitScale;
  const c0 = freeCentre();
  const mx = (c0.x - cam.tx) / cam.s;
  const my = (c0.y - cam.ty) / cam.s;
  measure();
  stopAnim();
  const s = fitScale * z;
  const { x, y } = freeCentre();
  setCam({ s, tx: x - mx * s, ty: y - my * s });
  fitPrompt();
}

// ── Hit testing and hover ───────────────────────────────────────────────

// Is screen point (x, y) on a blocking overlay (fill or outline)? Map
// units: the viewBox follows the camera, and overlays have no transform.
function blocked(x, y) {
  if (!blockers.length) return false;
  blockPoint.x = (x - cam.tx) / cam.s;
  blockPoint.y = (y - cam.ty) / cam.s;
  return blockers.some((b) => b.isPointInFill(blockPoint) || b.isPointInStroke(blockPoint));
}

// The answer (of the current round) at screen point (x, y), or null.
function hitTest(x, y, type) {
  if (renderQueued) render(); // the DOM must show the current camera
  const el = document.elementFromPoint(x, y);
  const piece = el && el.parentNode === regionsG ? el.id : null;
  // The answer of the piece under the pointer. An inert piece is context
  // land this round; a blocking overlay over the piece counts as
  // background (a drawn ring still wins; in a ring's wider zone both count
  // as sea).
  const owner = piece && !blocked(x, y) ? quiz.answerOf(piece) : null;
  const reach = MARKER_HIT[type] || MARKER_HIT.touch;
  let best = null;
  let bestD = Infinity;
  for (const [id, m] of rings) {
    if (!m.on) continue;
    const d = Math.hypot(m.x * cam.s + cam.tx - x, m.y * cam.s + cam.ty - y);
    // Inside the drawn ring the ring wins; in the wider zone only where no
    // other answer is under the pointer.
    const hit = d <= m.r + RING_SLACK || (d <= reach && (owner === null || owner === id));
    if (hit && d < bestD) {
      best = id;
      bestD = d;
    }
  }
  return best || owner;
}

let hovered = null; // answer id
let hoveredEls = []; // the elements hover was added to
let hoverAt = null;

function setHover(id) {
  if (id === hovered) return;
  for (const el of hoveredEls) el.classList.remove('hover');
  hovered = id;
  hoveredEls = id ? targets(id) : [];
  for (const el of hoveredEls) el.classList.add('hover');
  if (svg) svg.classList.toggle('over', !!id);
}

function queueHover(x, y) {
  const first = !hoverAt;
  hoverAt = { x, y };
  if (first) {
    requestAnimationFrame(() => {
      const p = hoverAt;
      hoverAt = null;
      if (p && !press) setHover(hitTest(p.x, p.y, 'mouse'));
    });
  }
}

// ── Pointer input ───────────────────────────────────────────────────────

const pointers = new Map(); // pointerId -> { x, y }
let press = null; // { x0, y0, type, moved, multi } while any pointer is down
let pinch = null; // { x, y, d } of the last two-finger move
let lastMouse = null;

function onDown(e) {
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  stopAnim();
  if (e.isPrimary) {
    // A primary pointer starts a fresh gesture: whatever is still listed
    // lost its up/cancel (e.g. capture failed and it ended elsewhere).
    pointers.clear();
    press = null;
    pinch = null;
  }
  try {
    svg.setPointerCapture(e.pointerId);
  } catch {
    // capture is a nicety (drags that leave the window)
  }
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pointers.size === 1) {
    press = { x0: e.clientX, y0: e.clientY, type: e.pointerType, moved: false, multi: false };
  } else if (press) {
    press.multi = true; // a second finger: this gesture never clicks
    press.moved = true;
    pinch = null;
  }
  if (e.pointerType !== 'mouse') setHover(null);
}

function onMove(e) {
  const p = pointers.get(e.pointerId);
  if (!p) {
    if (e.pointerType === 'mouse') {
      lastMouse = { x: e.clientX, y: e.clientY };
      queueHover(e.clientX, e.clientY);
    }
    return;
  }
  const px = p.x;
  const py = p.y;
  p.x = e.clientX;
  p.y = e.clientY;
  if (pointers.size >= 2) {
    pinchMove();
    return;
  }
  if (!press) return;
  if (!press.moved) {
    if (Math.hypot(p.x - press.x0, p.y - press.y0) < (SLOP[press.type] || SLOP.touch)) return;
    press.moved = true;
    svg.classList.add('panning');
    setHover(null);
    panBy(p.x - press.x0, p.y - press.y0);
    return;
  }
  panBy(p.x - px, p.y - py);
}

function pinchMove() {
  const [a, b] = pointers.values();
  const x = (a.x + b.x) / 2;
  const y = (a.y + b.y) / 2;
  const d = Math.max(1, Math.hypot(a.x - b.x, a.y - b.y));
  if (pinch) {
    // Move with the midpoint, then scale around it.
    const s = clampScale((cam.s * d) / pinch.d);
    const k = s / cam.s;
    const tx = cam.tx + (x - pinch.x);
    const ty = cam.ty + (y - pinch.y);
    setCam({ s, tx: x - (x - tx) * k, ty: y - (y - ty) * k });
  }
  pinch = { x, y, d };
}

function onUp(e, cancelled) {
  if (!pointers.delete(e.pointerId)) return;
  pinch = null;
  if (pointers.size) return;
  const p = press;
  press = null;
  svg.classList.remove('panning');
  if (!cancelled && p && !p.moved && !p.multi) pick(p.x0, p.y0, p.type);
  if (e.pointerType === 'mouse') queueHover(e.clientX, e.clientY);
}

// On window, not the SVG: a ctrl-wheel (Chrome / Firefox trackpad pinch,
// ctrl + mouse wheel) over the card or the controls would otherwise zoom
// the whole page; it zooms the map at the cursor. A plain wheel over the
// map pans (trackpad: the map follows the fingers, as the page would
// scroll) or zooms at the cursor (mouse); the kind is decided at the first
// event of a gesture and kept until a WHEEL_GAP_MS pause, so momentum
// scrolling stays a pan. A plain wheel over the HUD does nothing.
let wheelGesture = null; // 'trackpad' | 'mouse' while a gesture lasts
let wheelAt = -Infinity;

function onWheel(e) {
  const mode = e.deltaMode; // before deltaX / deltaY, see wheel.js
  const onMap = !!svg && svg.contains(e.target);
  if (!onMap && !e.ctrlKey) return; // plain wheel over the HUD: nothing to do
  e.preventDefault();
  if (!svg) return;
  stopAnim();
  const unit = mode === 1 ? 16 : mode === 2 ? view.h : 1;
  const now = performance.now();
  if (e.ctrlKey) {
    wheelGesture = null; // a pinch ends a scroll gesture
    // trackpad pinches send small deltas: zoom faster per unit
    zoomAt(e.clientX, e.clientY, Math.exp(-e.deltaY * unit * 0.01));
  } else {
    if (!wheelGesture || now - wheelAt > WHEEL_GAP_MS) wheelGesture = wheelKind(
      { deltaMode: mode, deltaX: e.deltaX, deltaY: e.deltaY, wheelDeltaY: e.wheelDeltaY },
      window.devicePixelRatio || 1,
    );
    if (wheelGesture === 'trackpad') panBy(-e.deltaX * unit, -e.deltaY * unit);
    else zoomAt(e.clientX, e.clientY, Math.exp(-e.deltaY * unit * 0.002));
  }
  wheelAt = now;
  root.dataset.wheel = wheelGesture || 'pinch';
  queueHover(e.clientX, e.clientY);
}

// Safari (macOS trackpad) pinches arrive as gesture events, not wheel.
let gestureScale = 1;
function onGesture(e) {
  e.preventDefault();
  if (e.type === 'gesturestart') gestureScale = 1;
  if (e.type !== 'gesturechange' || pointers.size >= 2) return; // touch pinches: pointer events
  const x = e.clientX ?? (lastMouse ? lastMouse.x : view.w / 2);
  const y = e.clientY ?? (lastMouse ? lastMouse.y : view.h / 2);
  zoomAt(x, y, e.scale / gestureScale);
  gestureScale = e.scale;
}

// ── Answers ─────────────────────────────────────────────────────────────

function pick(x, y, type) {
  const id = hitTest(x, y, type);
  if (!id) return; // sea, context land or an inert piece
  const res = quiz.answer(id);
  if (res.result === 'ignored') return;
  const els = elsOf(id, res.pieces);
  if (res.result === 'correct') {
    paintPieces(res.pieces);
    if (rings.has(id)) setColour(rings.get(id).ring, ringColour(res.pieces));
    unmarkEls(els, 'flash'); // picked right after a misclick on it
    if (labelId === id) hideLabel();
    markEls(els, 'pulse', PULSE_MS);
    if (res.completed) {
      roundDone(res.completed);
      enterRound();
    }
  } else {
    markEls(els, 'flash', LABEL_MS);
    showLabel(id, x, y, type);
  }
  updateHud();
  save();
}

let labelTimer = 0;
let labelId = null;
function hideLabel() {
  clearTimeout(labelTimer);
  labelEl.classList.remove('show');
  labelId = null;
}

// The misclick label: the round's miss text, and its missSub as a second,
// language-tagged part (e.g. "Aomori 青森").
function showLabel(id, x, y, type) {
  const round = ROUNDS[quiz.kind];
  const a = SPECS[quiz.kind].byId.get(id);
  labelId = id;
  const parts = [round.miss(a)];
  if (round.missSub) {
    const sub = document.createElement('span');
    sub.className = 'label-sub';
    if (round.subLang) sub.lang = round.subLang;
    sub.textContent = round.missSub(a);
    parts.push(' ', sub);
  }
  labelEl.replaceChildren(...parts);
  const w = labelEl.offsetWidth;
  const h = labelEl.offsetHeight;
  const lift = type === 'mouse' ? 16 : 44; // above the finger
  const lx = Math.min(view.w - w - 8, Math.max(8, x - w / 2));
  let ly = y - lift - h;
  const cr = card.getBoundingClientRect();
  const overCard = ly < cr.bottom + 4 && lx < cr.right && lx + w > cr.left;
  if (ly < insets().t + 4 || overCard) ly = y + (type === 'mouse' ? 18 : 36);
  labelEl.style.transform = `translate(${Math.round(lx)}px, ${Math.round(Math.min(ly, view.h - h - 8))}px)`;
  labelEl.classList.add('show');
  clearTimeout(labelTimer);
  labelTimer = setTimeout(hideLabel, LABEL_MS);
}

// A toast fades after `ms`; with ms = Infinity (the intro, on every load)
// it stays until the first interaction: a press anywhere on the page (map
// or controls: answers, pans, pinches, buttons), a wheel or gesture event,
// or a key. Any later toast replaces it and ends that.
let toastTimer = 0;
let toastUntilInteraction = false;
function toast(text, ms = TOAST_MS) {
  toastEl.textContent = text;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastUntilInteraction = ms === Infinity;
  if (!toastUntilInteraction) toastTimer = setTimeout(hideToast, ms);
}

function hideToast() {
  toastUntilInteraction = false;
  toastEl.classList.remove('show');
}

function interacted() {
  if (toastUntilInteraction) hideToast();
}
for (const t of ['pointerdown', 'wheel', 'gesturestart', 'keydown']) window.addEventListener(t, interacted, { capture: true, passive: true });

function roundDone({ kind, misses, total }) {
  toast(ROUNDS[kind].done({ total, misses }));
}

// A round starts (at load, after a completed round, after a reset): rings,
// colours, inert pieces and line overlays as this round has them; a
// misclick label of the round before goes.
function enterRound() {
  if (!svg) return;
  hideLabel();
  const was = hovered;
  setHover(null);
  if (buildRings()) queueRender(); // the new rings' radii, before the next paint
  paintAll();
  const round = ROUNDS[quiz.kind];
  for (const p of ids) {
    const inert = quiz.answerOf(p) === null;
    shapes[p].classList.toggle('inert', inert);
    if (inert) clearMarksOf([shapes[p]]); // context land doesn't pulse or blink
  }
  regionsG.classList.toggle('seamless', Array.isArray(round.lines));
  for (const [oid, el] of lineEls) el.classList.toggle('off', !(round.lines || []).includes(oid));
  // the pointer is still over the map: hover what lies there now
  if (was && lastMouse && !press) setHover(hitTest(lastMouse.x, lastMouse.y, 'mouse'));
}

// Rings for the round's answers that have a marker, rebuilt only when the
// set differs from the one drawn (one-piece rounds: never). True if rebuilt.
function buildRings() {
  if (!markersG) return false;
  const spec = SPECS[quiz.kind];
  const list = spec.answers.map((a) => spec.byId.get(a.id)).filter((c) => c.marker);
  const key = JSON.stringify(list.map((c) => [c.id, c.marker, c.size]));
  if (key === ringSet) return false;
  ringSet = key;
  clearMarksOf([...rings.values()].map((m) => m.ring));
  markersG.replaceChildren();
  rings.clear();
  for (const c of list) {
    const [x, y] = c.marker;
    const g = svgEl('g', {});
    const halo = svgEl('circle', { class: 'marker-halo', cx: x, cy: y, r: 1 });
    const ring = svgEl('circle', { class: 'marker', cx: x, cy: y, r: 1 });
    g.append(halo, ring);
    markersG.append(g);
    rings.set(c.id, { g, halo, ring, x, y, size: c.size, on: true });
  }
  return true;
}

// ── HUD ─────────────────────────────────────────────────────────────────

function updateHud() {
  const round = ROUNDS[quiz.kind];
  const a = SPECS[quiz.kind].byId.get(quiz.target);
  roundEl.textContent = round.label;
  progressEl.textContent = `${quiz.done} / ${quiz.total}`;
  correctEl.textContent = String(quiz.correct);
  missesEl.textContent = String(quiz.misses);
  promptKind.textContent = round.prompt;
  promptText.textContent = round.ask(a);
  if (promptSub) {
    // shown under the prompt, read with it (aria-live) from the sr-only copy
    const text = round.sub ? round.sub(a) : '';
    promptSub.textContent = text;
    promptSubSr.textContent = text ? ` ${text}` : '';
    for (const el of [promptSub, promptSubSr]) {
      if (text && round.subLang) el.lang = round.subLang;
      else el.removeAttribute('lang');
    }
  }
  if (swatch) swatch.classList.toggle('b', quiz.colour === 2);
  root.dataset.round = round.key;
  root.dataset.progress = `${quiz.done}/${quiz.total}`;
  fitPrompt();
}

// Long names shrink to fit the card instead of being cut off.
function fitPrompt() {
  promptEl.style.fontSize = '';
  const over = promptEl.scrollWidth - promptEl.clientWidth;
  if (over > 0) {
    const fs = parseFloat(getComputedStyle(promptEl).fontSize);
    promptEl.style.fontSize = `${Math.max(14, Math.floor((fs * promptEl.clientWidth) / promptEl.scrollWidth))}px`;
  }
}

let resetArmed = 0;
function disarmReset() {
  clearTimeout(resetArmed);
  resetArmed = 0;
  resetButton.classList.remove('armed');
  resetButton.setAttribute('aria-label', TEXT.reset);
}

resetButton.addEventListener('click', () => {
  if (!resetArmed) {
    resetButton.classList.add('armed');
    resetButton.setAttribute('aria-label', TEXT.resetArmed);
    resetArmed = setTimeout(disarmReset, RESET_ARM_MS);
    return;
  }
  disarmReset();
  quiz.reset();
  clearMarks();
  hideLabel();
  enterRound();
  updateHud();
  save();
  toast(TEXT.newGame, 2500);
});

// The theme toggle's label: theme.js keeps the state on <html> (no text);
// the words come from the config.
function labelTheme() {
  if (!themeButton || !root.dataset.theme) return;
  const other = root.dataset.theme === 'dark' ? 'light' : 'dark';
  const { label, title } = TEXT.theme(other, (root.dataset.themePref || 'auto') !== 'auto');
  themeButton.setAttribute('aria-label', label);
  themeButton.title = title;
}
new MutationObserver(labelTheme).observe(root, { attributes: true, attributeFilter: ['data-theme', 'data-theme-pref'] });
labelTheme();

// Optional second card line (rounds[].sub, e.g. a name in its own
// script): reserved in every round once any round has one, so the card
// keeps its height. Hidden from screen readers; a copy inside #prompt
// (sr-only, language-tagged) is read with the prompt.
let promptSub = null;
let promptSubSr = null;
if (ROUNDS.some((r) => r.sub)) {
  promptSub = document.createElement('p');
  promptSub.id = 'prompt-sub';
  promptSub.setAttribute('aria-hidden', 'true');
  promptEl.after(promptSub);
  promptSubSr = document.createElement('span');
  promptSubSr.className = 'sr-only';
  promptEl.append(promptSubSr);
  root.classList.add('has-sub');
}

// Optional data credit (e.g. CC BY): a line under the controls (portrait)
// or in the bottom-left corner (landscape), see style.css.
if (config.attribution) {
  const p = document.createElement('p');
  p.id = 'attribution';
  p.textContent = config.attribution;
  labelEl.before(p);
  root.classList.add('has-attribution');
}

zoomIn.addEventListener('click', () => zoomStep(ZOOM_STEP));
zoomOut.addEventListener('click', () => zoomStep(1 / ZOOM_STEP));
zoomFit.addEventListener('click', () => fitView(true));

window.addEventListener('keydown', (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey || !svg) return;
  switch (e.key) {
    case '+':
    case '=':
      zoomStep(ZOOM_STEP);
      break;
    case '-':
    case '_':
      zoomStep(1 / ZOOM_STEP);
      break;
    case '0':
      fitView(true);
      break;
    case 'ArrowLeft':
      panStep(1, 0);
      break;
    case 'ArrowRight':
      panStep(-1, 0);
      break;
    case 'ArrowUp':
      panStep(0, 1);
      break;
    case 'ArrowDown':
      panStep(0, -1);
      break;
    default:
      return;
  }
  e.preventDefault();
});

let resizeQueued = false;
window.addEventListener('resize', () => {
  if (resizeQueued) return;
  resizeQueued = true;
  requestAnimationFrame(() => {
    resizeQueued = false;
    relayout();
  });
});

// ── Start ───────────────────────────────────────────────────────────────

async function loadMap() {
  const res = await fetch('map.svg');
  if (!res.ok) throw new Error(`map.svg: HTTP ${res.status}`);
  const doc = new DOMParser().parseFromString(await res.text(), 'image/svg+xml');
  if (doc.documentElement.nodeName !== 'svg' || doc.querySelector('parsererror')) throw new Error('map.svg: not SVG');
  svg = document.importNode(doc.documentElement, true);
  // Every id in map.svg once, and none the page's or the engine's own (a
  // region sharing its id with an overlay would take #water's styles).
  const svgIds = new Set();
  for (const el of svg.querySelectorAll('[id]')) {
    if (svgIds.has(el.id)) throw new Error(`map.svg: id ${el.id} twice`);
    if (document.getElementById(el.id)) throw new Error(`map.svg: id ${el.id} is also an element id of the page`);
    if (/^(markers|fade(-.*)?)$/.test(el.id)) throw new Error(`map.svg: id ${el.id} is the engine's`);
    svgIds.add(el.id);
  }
  for (const id of ids) {
    shapes[id] = svg.querySelector('#' + CSS.escape(id));
    if (!shapes[id] || shapes[id].localName !== 'path') throw new Error(`map.svg: no <path> for ${id}`);
  }
  regionsG = shapes[ids[0]].parentNode;
  if (regionsG === svg || ids.some((id) => shapes[id].parentNode !== regionsG)) throw new Error('map.svg: the region shapes must share one <g>');
  regionsG.classList.add('regions');
  const overlay = (id, field) => {
    const el = svg.querySelector('#' + CSS.escape(id));
    if (!el || el.localName !== 'path' || !el.closest('#overlays')) throw new Error(`map.svg: no overlay <path id="${id}"> in #overlays (${field})`);
    return el;
  };
  for (const id of config.blockingOverlays || []) blockers.push(overlay(id, 'config.blockingOverlays'));
  for (const id of new Set(ROUNDS.flatMap((r) => r.lines || []))) {
    const el = overlay(id, 'rounds[].lines');
    el.classList.add('line');
    lineEls.set(id, el);
  }
  blockPoint = svg.createSVGPoint();
  // The fade only where context is drawn around the full view.
  if (MAP.extent[0] < 0 || MAP.extent[1] < 0) svg.append(fade());
  // The ring layer only if some round has an answer with a marker.
  if (SPECS.some((s) => s.answers.some((a) => s.byId.get(a.id).marker))) {
    markersG = svgEl('g', { id: 'markers' });
    svg.append(markersG);
  }
  host.append(svg);

  svg.addEventListener('pointerdown', onDown);
  svg.addEventListener('pointermove', onMove);
  svg.addEventListener('pointerup', (e) => onUp(e, false));
  svg.addEventListener('pointercancel', (e) => onUp(e, true));
  // Capture lost without an up (tab switch mid-drag …): end that pointer.
  // After a normal pointerup the pointer is already gone, so this no-ops.
  svg.addEventListener('lostpointercapture', (e) => onUp(e, true));
  svg.addEventListener('pointerleave', (e) => {
    if (e.pointerType === 'mouse' && !press) setHover(null);
  });
  svg.addEventListener('contextmenu', (e) => e.preventDefault());
  for (const t of ['gesturestart', 'gesturechange', 'gestureend']) document.addEventListener(t, onGesture);

  measure();
  fitView(false);
  enterRound();
  render();
  root.dataset.ready = '1';
}

window.addEventListener('wheel', onWheel, { passive: false });
updateHud();
loadMap().then(
  // the intro on every load (a reload is how to read it again), until the first interaction
  () => toast(coarse ? TEXT.intro.touch : TEXT.intro.mouse, Infinity),
  (err) => {
    root.dataset.ready = 'error';
    toast(TEXT.mapError, 1e9);
    console.error(err);
  },
);
if (!resumed) save();
